if(UnityEditor.EditorApplication.isPlayingOrWillChangePlaymode)throw new Exception("Finish Play Mode before changing the saved intro asset.");
const string clipPath="Assets/Assets/Video_Cutscene/LogicLegends_Opening_V4.mp4";
UnityEditor.AssetDatabase.ImportAsset(clipPath,UnityEditor.ImportAssetOptions.ForceSynchronousImport);
var clip=UnityEditor.AssetDatabase.LoadAssetAtPath<UnityEngine.Video.VideoClip>(clipPath);
if(clip==null)throw new Exception("The V4 cinematic did not import as a VideoClip.");
var previous=UnityEngine.SceneManagement.SceneManager.GetActiveScene();
var menu=UnityEngine.SceneManagement.SceneManager.GetSceneByPath("Assets/Scenes/Main Menu.unity");bool wasLoaded=menu.isLoaded;
if(!wasLoaded)menu=UnityEditor.SceneManagement.EditorSceneManager.OpenScene("Assets/Scenes/Main Menu.unity",UnityEditor.SceneManagement.OpenSceneMode.Additive);
if(menu.isDirty)throw new Exception("Main Menu has unsaved edits. Preserve them before assigning the clip.");
var auth=menu.GetRootGameObjects().SelectMany(r=>r.GetComponentsInChildren<AuthManager>(true)).Single();
var fields=new UnityEditor.SerializedObject(auth);
var video=(UnityEngine.Video.VideoPlayer)fields.FindProperty("introVideoPlayer").objectReferenceValue;
if(video==null)throw new Exception("The existing new-user intro VideoPlayer is missing.");
string oldClip=UnityEditor.AssetDatabase.GetAssetPath(video.clip);
var serialized=new UnityEditor.SerializedObject(video);serialized.FindProperty("m_VideoClip").objectReferenceValue=clip;serialized.ApplyModifiedPropertiesWithoutUndo();
UnityEditor.SceneManagement.EditorSceneManager.SaveScene(menu);
var result=new{oldClip,newClip=UnityEditor.AssetDatabase.GetAssetPath(video.clip),clipGuid=UnityEditor.AssetDatabase.AssetPathToGUID(clipPath),width=clip.width,height=clip.height,frames=clip.frameCount,duration=clip.length,audioTracks=clip.audioTrackCount,playOnAwake=video.playOnAwake,loop=video.isLooping,speed=video.playbackSpeed,source=video.source.ToString(),mainMenuSaved=!menu.isDirty};
if(previous.IsValid()&&previous.isLoaded)UnityEngine.SceneManagement.SceneManager.SetActiveScene(previous);
if(!wasLoaded)UnityEditor.SceneManagement.EditorSceneManager.CloseScene(menu,true);
return result;
